package scp_candidate.EIT_Acquisition_Supervisor

import org.sireum._
import art._
import scp_candidate._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait EquipmentAssessment_Api {
  def id: Art.BridgeId
  def equipment_observation_Id : Art.PortId
  def equipment_facts_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var equipment_facts: EIT_Acquisition_Supervisor.EquipmentFacts.Type = $

  def put_equipment_facts(value : EIT_Acquisition_Supervisor.EquipmentFacts.Type) : Unit = {
    Contract(
      Modifies(equipment_facts),
      Ensures(
        equipment_facts == value
      )
    )
    Spec {
      equipment_facts = value
    }

    Art.putValue(equipment_facts_Id, EIT_Acquisition_Supervisor.EquipmentFacts_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class EquipmentAssessment_Initialization_Api (
  val id: Art.BridgeId,
  val equipment_observation_Id : Art.PortId,
  val equipment_facts_Id : Art.PortId) extends EquipmentAssessment_Api

@datatype class EquipmentAssessment_Operational_Api (
  val id: Art.BridgeId,
  val equipment_observation_Id : Art.PortId,
  val equipment_facts_Id : Art.PortId) extends EquipmentAssessment_Api {

  // Logika spec var representing port state for incoming data port
  @spec var equipment_observation: EIT_Acquisition_Supervisor.EquipmentObservation.Type = $

  def get_equipment_observation() : Option[EIT_Acquisition_Supervisor.EquipmentObservation.Type] = {
    Contract(
      Ensures(
        Res == Some(equipment_observation)
      )
    )
    val value : Option[EIT_Acquisition_Supervisor.EquipmentObservation.Type] = Art.getValue(equipment_observation_Id) match {
      case Some(EIT_Acquisition_Supervisor.EquipmentObservation_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port equipment_observation.  Expecting 'EIT_Acquisition_Supervisor.EquipmentObservation_Payload' but received ${v}")
        None[EIT_Acquisition_Supervisor.EquipmentObservation.Type]()
      case _ => None[EIT_Acquisition_Supervisor.EquipmentObservation.Type]()
    }
    return value
  }
}
